const { LRUCache } = require('./src/lru');
const assert = require('node:assert/strict');
for (const c of [0, -1, 1.5, Infinity, NaN, '3', undefined, null]) {
  assert.throws(() => new LRUCache(c), RangeError, 'capacity ' + c);
}
const c = new LRUCache(2);
c.set('a', undefined).set('b', 2);
c.get('a'); // refresh undefined entry
c.set('d', 4);
assert.equal(c.has('a'), true);
assert.equal(c.has('b'), false);
c.set('a', 9); // update: no eviction, no size growth
assert.equal(c.size, 2);
assert.equal(c.get('a'), 9);
const o = {}; const x = new LRUCache(1);
x.set(o, 'obj'); assert.equal(x.get(o), 'obj'); // Map key semantics
const i = new LRUCache(1); // independence
assert.equal(i.size, 0);
console.log('all edge cases OK');
